use serde_json::json;
use std::collections::BTreeMap;
use verified_language::{core::{CheckedModule,Type},definition_context::DefinitionContext,eval,laws::{Catalogue,Law,Proof,SEMANTICS},optimisation::{self,Package,Site},registry,semantic::{self as s},stateful::Runtime,syntax};
#[path="support/parity.rs"]mod parity;
#[test]
fn flat_source_context_and_demand_normalization_preserve_every_cpu_boundary(){
 let mut source="module demand;record Pair{slow:u32,fast:u32,}fn make(x:u32)->Pair{".to_string();for i in 0..26{source.push_str(&format!("let v{i}=x+{i};"));}source.push_str("return Pair{slow:repeat(128,x,fn(i,value)=>value+1),fast:x};}fn observed(x:u32)->u32{let pair=make(x);return pair.fast;}enum Error{Rejected,}private state Saved:u32=0;event value:u32;change save(x:u32,reject:Bool)->Result<u32,Error> writes(Saved) emits(value){let n=observed(x);Saved=n;emit value(n);return choose(reject,Err(Error.Rejected),Ok(n));}");
 let program=syntax::parse(&source).unwrap();let module=CheckedModule::from_source(program.clone()).unwrap();let f=program.functions.iter().find(|f|f.name=="observed").unwrap();let context=DefinitionContext::capture(&module,&["make".into()]).unwrap();assert!(context.definitions["make"].definition.compact_body);
 let scalar=s::value(Type::U32);let x=s::free(scalar.clone(),"x");let theorem=Law{schema:1,semantics:SEMANTICS.into(),params:BTreeMap::from([("x".into(),scalar)]),conditions:vec![],from:s::elaborate(&f.body,&verified_language::check::params_env(&f.params).unwrap(),&program,&f.result).unwrap(),to:x.clone(),proof:Proof::Normalize,dependencies:vec![],definition_context:Some(context),types:vec![],assumptions:vec![]};let id=registry::identity(&registry::Entry::from_law(&theorem).unwrap()).unwrap();
 let package=Package{schema:1,semantics:optimisation::SEMANTICS.into(),input_core_sha256:module.identity().unwrap(),knowledge:registry::from_catalogue(&Catalogue{schema:1,semantics:SEMANTICS.into(),roots:vec![id.clone()],objects:BTreeMap::from([(id.clone(),theorem)])}).unwrap(),applications:vec![Site{function:"observed".into(),path:vec![],law:id,arguments:BTreeMap::from([("x".into(),x)]),premises:vec![]}],action_replacement:None,contract_refinement:None};
 registry::CheckedBundle::check(&package.knowledge).unwrap();let checked=optimisation::check(&module,&package).unwrap();let mut baseline=Runtime::new(program.clone()).unwrap();let mut runtime=Runtime::new_selected(&checked).unwrap();let mut steps=vec![];let mut expected=vec![];
 for value in [0u32,17,u32::MAX]{assert_eq!(eval::call(&program,"observed",vec![eval::Value::U32(value)],&mut 100000).unwrap().json(),json!(value));steps.push(json!({"pure":"observed","args":[value]}));expected.push(json!({"reply":{"value":value},"snapshot":runtime.checkpoint_portable().unwrap()}));}
 for (value,reject)in [(17,false),(29,true),(u32::MAX,false)]{let args=json!([value,reject]);let before=runtime.checkpoint_portable().unwrap();let out=runtime.invoke_json("save",&args).unwrap();assert_eq!(out.json(),baseline.invoke_json("save",&args).unwrap().json());assert_eq!(runtime.checkpoint_portable().unwrap(),baseline.checkpoint_portable().unwrap());if reject{assert!(!out.committed);assert!(out.events.is_empty());assert_eq!(runtime.checkpoint_portable().unwrap(),before);}else{assert!(out.committed);assert_eq!(out.events.len(),1);}steps.push(json!({"call":"save","args":args}));expected.push(json!({"reply":{"outcome":out.json()},"snapshot":runtime.checkpoint_portable().unwrap()}));}
 parity::conformance_selected("flat-demand-context-parity",&checked,&source,steps,expected);
}
